using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.SemanticKernel.TemplateEngine;
using Xunit;
using Moq;

namespace SemanticKernel.Core.Tests.TemplateEngine.Blocks
{
    // Minimal stub for BlockTypes enum
    internal enum BlockTypes
    {
        Undefined,
        Value,
        Variable,
        FunctionId,
        NamedArg,
        Code
    }

    // Minimal stub for Block base class
    internal abstract class TestBlock : Block
    {
        private readonly BlockTypes _type;
        private readonly string _content;

        protected TestBlock(BlockTypes type, string content, ILoggerFactory? loggerFactory = null)
            : base(content, loggerFactory)
        {
            _type = type;
            _content = content;
        }

        internal override BlockTypes Type => _type;

        public override bool IsValid(out string errorMsg)
        {
            errorMsg = "";
            return true;
        }
    }

    // Minimal stub for ITextRendering interface
    internal interface ITextRendering
    {
        object? Render(KernelArguments? arguments);
    }

    // Minimal stub for KernelArguments class
    internal class KernelArguments
    {
    }

    // Minimal stub for Kernel class
    internal class Kernel
    {
    }

    // TestBlock implementing ITextRendering
    internal class TestTextRenderingBlock : TestBlock, ITextRendering
    {
        public TestTextRenderingBlock(string content, ILoggerFactory? loggerFactory = null)
            : base(BlockTypes.Value, content, loggerFactory)
        {
        }

        public object? Render(KernelArguments? arguments)
        {
            return "rendered";
        }
    }

    public class CodeBlockTests
    {
        [Fact]
        public async Task RenderCodeAsync_LogsTrace_WhenTraceEnabled()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var loggerFactoryMock = new Mock<ILoggerFactory>();
            loggerFactoryMock.Setup(f => f.CreateLogger(It.IsAny<Type>())).Returns(loggerMock.Object);
            loggerMock.Setup(l => l.IsEnabled(LogLevel.Trace)).Returns(true);

            var blocks = new List<Block> { new TestTextRenderingBlock("content", loggerFactoryMock.Object) };
            var codeBlock = new CodeBlock(blocks, "content", loggerFactoryMock.Object);

            // Mark as validated to skip IsValid check
            var validatedField = typeof(CodeBlock).GetField("_validated", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            validatedField.SetValue(codeBlock, true);

            var kernel = new Kernel();

            // Act
            var result = await codeBlock.RenderCodeAsync(kernel);

            // Assert
            loggerMock.Verify(l => l.Log(
                LogLevel.Trace,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Rendering code: `content`")),
                null,
                It.IsAny<Func<It.IsAnyType, Exception?, string>>()),
                Times.Once);

            Assert.Equal("rendered", result);
        }
    }
}
